//! Official Yamaha PSR-E583 Voice & Drum Kit Database (890 onboard voices + Standard Kit 1 Drum Keymap).
//! Extracted directly from the official Yamaha PSR-E483 / PSR-E583 Data List.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct VoiceEntry {
    /// 1-based Voice Number on the PSR-E583 panel (1..=890).
    pub voice_no: u16,
    /// Official Voice Name on the PSR-E583.
    pub name: &'static str,
    /// Panel / XGlite Category.
    pub category: &'static str,
    /// Bank Select MSB (CC#0), 0..=127. `None` if panel-only (Dual/Harmony/Arp).
    pub msb: Option<u8>,
    /// Bank Select LSB (CC#32), 0..=127. `None` if panel-only.
    pub lsb: Option<u8>,
    /// 0-based MIDI Program Change (0..=127, i.e., Data List PC# minus 1).
    pub pc: Option<u8>,
    /// Special flags (`"*"` = Dual, `"**"` = Harmony, `"***"` = S.Art Lite).
    pub flags: &'static str,
}

impl VoiceEntry {
    pub const fn is_midi_selectable(&self) -> bool {
        self.msb.is_some() && self.lsb.is_some() && self.pc.is_some()
    }

    pub const fn is_drum_kit(&self) -> bool {
        self.voice_no >= 353 && self.voice_no <= 392
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct DrumNoteEntry {
    /// MIDI Note Number (13..=91) transmitted in the `.sty` file.
    pub midi_note: u8,
    /// MIDI Note label (e.g. "C1", "D1", "F#1").
    pub midi_note_name: &'static str,
    /// Keyboard Note label printed on Yamaha Data List (one octave higher than MIDI).
    pub keyboard_note_name: &'static str,
    /// Standard Kit 1 instrument name.
    pub standard_name: &'static str,
    /// Real Drum Kit override name (if different from Standard Kit 1).
    pub real_kit_name: Option<&'static str>,
    /// Group category for the Drum Machine UI (Kick, Snare, Hi-Hat, Cymbal, Tom, Latin/Perc, SFX).
    pub group: &'static str,
}

